candidates.raw:
    adcs_quat_t n;
    adcs_status_t st;
    int i;
    double comp[4];

    if ((q == NULL) || (canonical == NULL)) {
        return ADCS_E_NULL;
    }

    st = adcs_quat_normalize(q, &n);
    if (st != ADCS_OK) {
        return ADCS_E_DEGENERATE;
    }

    comp[0] = n.w;
    comp[1] = n.x;
    comp[2] = n.y;
    comp[3] = n.z;
    for (i = 0; i < 4; i++) {
        if (comp[i] != 0.0) {
            if (comp[i] < 0.0) {
                n.w = -n.w;
                n.x = -n.x;
                n.y = -n.y;
                n.z = -n.z;
            }
            break;
        }
    }

    *canonical = n;
    return ADCS_OK;
}

